mapper.select:
SELECT *
FROM point_cloud_data
WHERE robot_id = #{robotId}
  AND frame_id = #{frameId}
ORDER BY timestamp DESC

SELECT *
FROM image_data
WHERE robot_id = #{robotId}
  AND session_id = #{sessionId}
ORDER BY timestamp DESC

SELECT DISTINCT frame_id
FROM point_cloud_data
WHERE robot_id = #{robotId}
  AND reception_count = #{receptionCount}
ORDER BY frame_id ASC

SELECT DISTINCT session_id
FROM image_data
WHERE robot_id = #{robotId}
  AND reception_count = #{receptionCount}
ORDER BY session_id ASC

SELECT
    id, timestamp, file_path, point_count, reception_count, frame_id
FROM
    point_cloud_data
WHERE
    robot_id = #{robotId}
  AND frame_id = #{frame}
  AND reception_count = #{receptionCount}
ORDER BY
    timestamp DESC

SELECT
    id, timestamp, file_path, format, reception_count, session_id, width, height
FROM
    image_data
WHERE
    robot_id = #{robotId}
  AND session_id = #{session}
  AND reception_count = #{receptionCount}
ORDER BY
    timestamp DESC
